 public static void main(String[] args)throws java.lang.Exception{IDictionary d=null;OracleDataKey stored=null,query=null;int groups=0,profiles=0,steps=0;for(String line:Files.readAllLines(Path.of(args[0]))){String[] p=line.split("\t",-1);if(p[0].equals("N")){int hash=Integer.parseInt(p[3]);stored=new OracleDataKey(1,Integer.parseInt(p[1]),p[4].equals("1"),hash==1||hash==3);query=p[6].equals("1")?stored:new OracleDataKey(2,Integer.parseInt(p[2]),p[5].equals("1"),hash==2||hash==3);d=new Exception("data").get_Data();profiles++;continue;}final IDictionary dictionary=d;final OracleDataKey s=stored,q=query;if(p[0].equals("I")){check(outcome(()->{dictionary.Add(s,"initial");return null;},"void").equals(p[1]),"initial "+line);groups++;continue;}
 IEnumerator[] cursors={d.GetEnumerator(),d.get_Keys().GetEnumerator(),d.get_Values().GetEnumerator()};for(int i=0;i<3;i++){final IEnumerator c=cursors[i];check(outcome(c::MoveNext,"bool").equals(p[2+i]),"before move "+line);groups++;}String result=switch(p[1]){case "read"->outcome(()->dictionary.get_Item(q),"value");case "contains"->outcome(()->dictionary.Contains(q),"bool");case "write"->outcome(()->{dictionary.set_Item(q,"updated");return null;},"void");case "add"->outcome(()->{dictionary.Add(q,"added");return null;},"void");case "remove","removeEmpty"->outcome(()->{dictionary.Remove(q);return null;},"void");case "clear","clearEmpty"->outcome(()->{dictionary.Clear();return null;},"void");default->throw new AssertionError(p[1]);};check(result.equals(p[5]),"outcome "+line+" actual="+result);groups++;
 for(int i=0;i<3;i++){final IEnumerator c=cursors[i];int offset=10+i*3;check(outcome(c::get_Current,"current").equals(p[offset]),"current "+line);check(outcome(c::MoveNext,"bool").equals(p[offset+1]),"move "+line);check(outcome(()->{c.Reset();return null;},"void").equals(p[offset+2]),"reset "+line);groups+=3;}
 check(d.get_Count()==Integer.parseInt(p[6]),"count "+line);check(contents(d).equals(p[7]),"contents "+line+" actual="+contents(d));check(counters(stored).equals(p[8]),"stored callbacks "+line+" actual="+counters(stored));check(counters(query).equals(p[9]),"query callbacks "+line+" actual="+counters(query));groups+=4;steps++;
 }java.lang.System.out.println("PASS Data key matching profiles="+profiles+" steps="+steps+" groups="+groups);}
